g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   for a,b in q:
    comp.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<R and 0<=y<C and g[x][y]==0 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   comps.append(comp)
[(len(x), sorted(x), any(r in (0,R-1) or c in (0,C-1) for r,c in x)) for x in comps]
